import {
  APPROVAL_STATUSES,
  DATA_SENSITIVITY_LEVELS,
  DEFAULT_GOVERNANCE_TEMPLATE,
  GOVERNANCE_SECTIONS,
  RISK_LEVELS
} from './schema.js';

export { APPROVAL_STATUSES, DATA_SENSITIVITY_LEVELS, GOVERNANCE_SECTIONS, RISK_LEVELS };

const isPlainObject = (value) => Boolean(value) && typeof value === 'object' && !Array.isArray(value);

